import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Claude Code — El planificador ejecutor","description":"Claude Code: planificación multipaso, uso de herramientas y ediciones en todo el código con precisión quirúrgica. El agente detrás de este mismo sitio.","frontmatter":{"title":"Claude Code — El planificador ejecutor","description":"Claude Code: planificación multipaso, uso de herramientas y ediciones en todo el código con precisión quirúrgica. El agente detrás de este mismo sitio."},"headers":[],"relativePath":"es/agentic/claude-code/index.md","filePath":"es/agentic/claude-code/index.md"}`),a={name:`es/agentic/claude-code/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="claude-code-—-el-planificador-ejecutor" tabindex="-1">Claude Code — El planificador ejecutor <a class="header-anchor" href="#claude-code-—-el-planificador-ejecutor" aria-label="Permalink to “Claude Code — El planificador ejecutor”">​</a></h1><p><strong>Claude Code</strong> es la CLI agéntica de Anthropic, y ocupa un asiento específico en mi flujo: el <strong>planificador ejecutor</strong>. Mientras otros agentes brillan por velocidad o escala, Claude Code brilla por <em>profundidad</em> — mantiene una base de código entera en la cabeza, planifica cambios multipaso y los ejecuta con precisión quirúrgica en docenas de archivos.</p><h2 id="que-lo-hace-diferente" tabindex="-1">Qué lo hace diferente <a class="header-anchor" href="#que-lo-hace-diferente" aria-label="Permalink to “Qué lo hace diferente”">​</a></h2><ul><li><strong>Planifica antes de tocar código.</strong> Para cualquier tarea no trivial produce un plan explícito que puedo corregir — el lugar más barato posible para arreglar un error.</li><li><strong>Ediciones en toda la base.</strong> Busca, entiende y luego edita coherentemente — no parches ciegos archivo por archivo.</li><li><strong>Disciplina de herramientas.</strong> Muestra su trabajo: comandos ejecutados, tests corridos, diffs preparados.</li><li><strong>Buen gusto.</strong> En la práctica, sus refactors se leen como de un senior cuidadoso, lo que minimiza mi superficie de revisión.</li></ul><blockquote><p>Este portafolio es una obra de Claude Code: un clon completo del tema VitePress adaptado a cuatro idiomas con soporte RTL — planificado una vez, revisado por mí, enviado en esta forma.</p></blockquote><h2 id="como-le-paso-el-brief" tabindex="-1">Cómo le paso el brief <a class="header-anchor" href="#como-le-paso-el-brief" aria-label="Permalink to “Cómo le paso el brief”">​</a></h2><p>Cuanto mejor sea el plan que puedo criticar, mejor el resultado. Así que mis briefs para Claude Code declaran el objetivo, las restricciones y la definición de hecho — e invitan explícitamente a un plan antes de ejecutar. Luego hago lo mío: leo el plan, ataco los puntos débiles, y solo entonces lo dejo correr. El patrón está descrito en <a href="/Usf/es/about/how-i-work/">El método agéntico</a>.</p><p>Claude Code también juega el rol de integrador después de los abanicos de <a href="/Usf/es/agentic/codex/">Codex</a>: reconcilia diffs, resuelve solapamientos y corre la suite completa antes de que algo llegue a una rama que me importa.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};